function Seal({ size = 64 }) {
  const cx = size / 2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ display: "block" }}>
      <circle cx={cx} cy={cx} r={size * 0.46} fill="none" stroke="var(--gold)" strokeWidth="0.6" opacity="0.5" />
      <circle cx={cx} cy={cx} r={size * 0.34} fill="none" stroke="var(--gold)" strokeWidth="0.6" opacity="0.35" />
      <polygon
        points={Array.from({ length: 6 }, (_, i) => {
          const a = (i * Math.PI) / 3 - Math.PI / 2;
          const r = size * 0.34;
          return `${cx + Math.cos(a) * r},${cx + Math.sin(a) * r}`;
        }).join(" ")}
        fill="none"
        stroke="var(--gold)"
        strokeWidth="0.6"
        opacity="0.55"
      />
      <circle cx={cx} cy={cx} r="2.2" fill="var(--gold)" />
    </svg>
  );
}

function BookCover({ book, w = 150 }) {
  if (book.image) {
    return (
      <img
        className="coverArt"
        src={book.image}
        alt={book.title}
        style={{ width: w, height: "auto", display: "block", border: "1px solid var(--line)", boxShadow: "0 18px 40px -22px rgba(0,0,0,0.9)", flexShrink: 0 }}
      />
    );
  }
  const h = w * 1.5;
  return (
    <div
      className="coverArt"
      style={{
        width: w,
        height: h,
        background: `linear-gradient(155deg, ${book.cover[0]}, ${book.cover[1]})`,
        border: "1px solid var(--line)",
        position: "relative",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-between",
        padding: w * 0.11,
        flexShrink: 0,
        boxShadow: "0 18px 40px -22px rgba(0,0,0,0.9)",
      }}
    >
      <div style={{ position: "absolute", inset: 6, border: "1px solid var(--lineSoft)", pointerEvents: "none" }} />
      <div style={{ fontFamily: "var(--mono)", fontSize: w * 0.05, letterSpacing: "0.3em", color: "var(--gold)", textTransform: "uppercase" }}>
        Codex · {book.seal}
      </div>
      <div>
        <div style={{ fontFamily: "var(--display)", fontStyle: "italic", fontWeight: 400, fontSize: w * 0.12, lineHeight: 1.15, color: "var(--ink)" }}>
          {book.title.split(":")[0]}
        </div>
        <div style={{ width: w * 0.22, height: 1, background: "var(--gold)", margin: `${w * 0.06}px 0`, opacity: 0.6 }} />
        <div style={{ fontFamily: "var(--mono)", fontSize: w * 0.045, letterSpacing: "0.25em", color: "var(--inkFaint)", textTransform: "uppercase" }}>
          {AUTHOR}
        </div>
      </div>
    </div>
  );
}

function EmailCapture({ heading = "Join the Codex", compact = false }) {
  const [email, setEmail] = useState("");
  const [done, setDone] = useState(false);
  const submit = async () => {
    if (!email || !email.includes("@")) return;
    // Posts to the secure /api/subscribe route once deployed. Harmless no-op in preview.
    try {
      await fetch("/api/subscribe", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) });
    } catch (e) {}
    setDone(true);
  };
  return (
    <div style={{ ...styles.emailBox, ...(compact ? { padding: "28px 24px" } : {}) }}>
      <div style={styles.sectionEyebrow}>{compact ? "The Codex Letter" : "Owned · Not Borrowed"}</div>
      <h3 style={{ ...styles.emailHeading, fontSize: compact ? 26 : 32 }}>{heading}</h3>
      {!compact && (
        <p style={styles.emailSub}>
          New books, new guides, research notes, early releases, and library updates. Sent when there is something real to send. No noise.
        </p>
      )}
      {done ? (
        <div style={styles.emailDone}>✦ You're in. Watch your inbox for the welcome note.</div>
      ) : (
        <div style={styles.emailRow}>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            placeholder="your@email.com"
            style={styles.emailInput}
          />
          <button onClick={submit} style={styles.emailBtn} className="emailBtnHover">
            Join
          </button>
        </div>
      )}
    </div>
  );
}

function EntryModal({ onClose }) {
  const [email, setEmail] = useState("");
  const [done, setDone] = useState(false);
  const submit = async () => {
    if (!email || !email.includes("@")) return;
    try {
      await fetch("/api/subscribe", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) });
    } catch (e) {}
    setDone(true);
    setTimeout(onClose, 1500);
  };
  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <div style={styles.modalOverlay} className="modalOverlay" onClick={onClose}>
      <div style={styles.modalCard} className="modalCard" onClick={(e) => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 18 }}><Seal size={46} /></div>
        <div style={styles.modalEyebrow}>The Architect Codex</div>
        <h2 style={styles.modalTitle}>Enter The Codex</h2>
        {done ? (
          <div style={styles.modalDone}>✦ You are in. Watch your inbox.</div>
        ) : (
          <>
            <p style={styles.modalSub}>Join the private Codex list for new books, guides, research notes, and library updates.</p>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && submit()}
              placeholder="your@email.com"
              style={styles.modalInput}
            />
            <button onClick={submit} style={styles.modalBtn} className="btnPrimaryHover">Enter The Codex</button>
            <button onClick={onClose} style={styles.modalSkip} className="modalSkipHover">Continue Without Joining</button>
          </>
        )}
      </div>
    </div>
  );
}

