export default function ArchitectCodex() {
  const [route, setRoute] = useState({ page: "home", param: null });
  const [query, setQuery] = useState("");
  const [menu, setMenu] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);

  const go = (page, param = null) => {
    setRoute({ page, param });
    setMenu(false);
    if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "instant" });
  };

  const dismissModal = () => {
    setModalOpen(false);
    try { localStorage.setItem("codex_entry_seen", "1"); } catch (e) {}
  };

  useEffect(() => {
    try { if (localStorage.getItem("codex_entry_seen")) return; } catch (e) {}
    const t = setTimeout(() => setModalOpen(true), 900);
    return () => clearTimeout(t);
  }, []);

  let body;
  switch (route.page) {
    case "books": body = <Books go={go} />; break;
    case "book": body = <BookDetail slug={route.param} go={go} />; break;
    case "library": body = <Library go={go} />; break;
    case "category": body = <Category id={route.param} go={go} />; break;
    case "guide": body = <GuideDetail slug={route.param} go={go} />; break;
    case "article": body = <ArticleDetail slug={route.param} go={go} />; break;
    case "community": body = <Community go={go} />; break;
    case "work": body = <Work />; break;
    case "about": body = <About go={go} />; break;
    case "privacy": body = <Privacy />; break;
    case "search": body = <Search go={go} query={query} setQuery={setQuery} />; break;
    default: body = <Home go={go} />;
  }

  return (
    <div style={styles.app}>
      <style>{globalStyles}</style>
      <div style={styles.bgGradient} />
      <div style={styles.bgNoise} />
      {modalOpen && <EntryModal onClose={dismissModal} />}

      {/* NAV */}
      <header style={styles.nav}>
        <div style={styles.navInner}>
          <div onClick={() => go("home")} style={styles.navBrand} className="navBrandHover">
            <Seal size={26} />
            <span style={styles.navBrandText}>{BRAND}</span>
          </div>
          <nav style={styles.navLinks} className="navLinksDesktop">
            {NAV.map((n) => (
              <span
                key={n.id}
                onClick={() => go(n.id)}
                style={{ ...styles.navLink, ...(route.page === n.id ? styles.navLinkActive : {}) }}
                className="navLinkHover"
              >
                {n.label}
              </span>
            ))}
            <span onClick={() => go("search")} style={styles.navSearch} className="navLinkHover">⌕ Search</span>
          </nav>
          <button onClick={() => setMenu(!menu)} style={styles.menuBtn} className="navLinksMobile">{menu ? "✕" : "☰"}</button>
        </div>
        {menu && (
          <div style={styles.mobileMenu}>
            {NAV.map((n) => (
              <span key={n.id} onClick={() => go(n.id)} style={styles.mobileLink}>{n.label}</span>
            ))}
            <span onClick={() => go("search")} style={styles.mobileLink}>⌕ Search</span>
          </div>
        )}
      </header>

      <main style={styles.main} key={route.page + (route.param || "")}>
        <div className="pageFade">{body}</div>
      </main>

      {/* FOOTER */}
      <footer style={styles.footer}>
        <div style={{ marginBottom: 48 }}>
          <EmailCapture heading="Join the Codex" compact />
        </div>
        <div style={styles.footerCols}>
          <div style={styles.footerCol}>
            <div style={styles.footerHead}>Codex</div>
            <span onClick={() => go("home")} style={styles.footerLink} className="footerLinkHover">Home</span>
            <span onClick={() => go("about")} style={styles.footerLink} className="footerLinkHover">About</span>
            <span onClick={() => go("books")} style={styles.footerLink} className="footerLinkHover">Books</span>
            <span onClick={() => go("community")} style={styles.footerLink} className="footerLinkHover">Community</span>
            <span onClick={() => go("library")} style={styles.footerLink} className="footerLinkHover">Library</span>
            <span onClick={() => go("work")} style={styles.footerLink} className="footerLinkHover">Sessions</span>
            <span onClick={() => go("privacy")} style={styles.footerLink} className="footerLinkHover">Privacy</span>
          </div>
          <div style={styles.footerCol}>
            <div style={styles.footerHead}>Find Me</div>
            {SOCIALS.map((s) => (
              <a key={s.name} href={s.url} target="_blank" rel="noopener noreferrer" style={styles.footerLink} className="footerLinkHover">{s.name}</a>
            ))}
          </div>
        </div>
        <div style={styles.footerBottom}>
          <Seal size={22} />
          <a href={`mailto:${CONTACT_EMAIL}`} style={styles.footerEmail}>{CONTACT_EMAIL}</a>
          <div style={styles.footerDisclaimer}>The Architect Codex explores consciousness, reality, meaning, and human experience. It is not medical, psychological, legal, or psychiatric advice.</div>
          <div style={styles.footerCopy}>© {new Date().getFullYear()} {BRAND} · All rights reserved</div>
        </div>
      </footer>
    </div>
  );
}

